"""Stage covers in 10,000-image zip batches, then verify and finalize uploads.

IDs are ten decimal digits: four for the million-image item, two for the
10,000-image batch, and four within that batch. Each size has its own item.
"""

import contextlib
import fcntl
import os
import re
import time
import zipfile
from subprocess import run

from openlibrary.coverstore import config, db

SIZES = ('', 's', 'm', 'l')


def _size(size):
    size = size.lower()
    if size not in SIZES:
        raise ValueError(f'invalid cover size: {size}')
    return size


class Cover:
    def __init__(self, attributes):
        self.__dict__.update(dict(attributes))

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        cover_id = int(cover_id)
        if not 0 <= cover_id < 10**10:
            raise ValueError('cover ID must fit in ten digits')
        digits = f'{cover_id:010d}'
        return digits[:4], digits[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        size = _size(size)
        if protocol not in ('http', 'https'):
            raise ValueError('protocol must be http or https')
        ext = ext.lstrip('.')
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        suffix = f'-{size.upper()}' if size else ''
        digits = f'{int(cover_id):010d}'
        return (f'{protocol}://archive.org/download/{prefix}covers_{item_id}/'
                f'{prefix}covers_{item_id}_{batch_id}.zip/{digits}{suffix}.{ext}')

    def files(self):
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            filename = getattr(self, field, None)
            if filename:
                yield size, field, os.path.join(config.data_root, 'localdisk', filename)

    def valid_files(self):
        files = list(self.files())
        return len(files) == len(SIZES) and all(os.path.isfile(p) for _, _, p in files)

    def delete_files(self):
        for _, _, path in self.files():
            os.remove(path)


class Batch:
    def __init__(self, item_id, batch_id, size=''):
        self.item_id, self.batch_id = item_id, batch_id
        self.size = _size(size) if size else ''

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        size = _size(size)
        prefix = f'{size}_' if size else ''
        return os.path.join('items', f'{prefix}covers_{item_id}',
                            f'{prefix}covers_{item_id}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @contextlib.contextmanager
    def lock(self):
        item_id, batch_id = self._norm_ids()
        path = os.path.join(config.data_root, 'items', '.locks', f'{item_id}_{batch_id}.lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as lockfile:
            fcntl.flock(lockfile, fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        """Upload staged zip files and finalize only after all four are present remotely."""
        uploader = uploader or Uploader()
        with self.lock():
            item_id, batch_id = self._norm_ids()
            sizes = (self.size,) if self.size else SIZES
            for size in sizes:
                path = self.get_abspath(item_id, batch_id, size)
                if not os.path.isfile(path):
                    continue
                prefix = f'{size}_' if size else ''
                item = f'{prefix}covers_{item_id}'
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
                if finalize and not uploader.is_uploaded(item, os.path.basename(path)):
                    raise RuntimeError(f'upload not verified: {item}/{os.path.basename(path)}')
            if finalize and not test:
                # A cover is complete only when every size is available remotely.
                for size in SIZES:
                    prefix = f'{size}_' if size else ''
                    item = f'{prefix}covers_{item_id}'
                    filename = os.path.basename(self.get_relpath(item_id, batch_id, size))
                    if not uploader.is_uploaded(item, filename):
                        raise RuntimeError(f'upload not verified: {item}/{filename}')
                self.finalize(item_id * 1_000_000 + batch_id * 10_000)

    def finalize(self, start_id=None, test=False):
        if not test:
            item_id, batch_id = self._norm_ids()
            CoverDB.update_completed_batch(item_id, batch_id)
            for size in SIZES:
                path = self.get_abspath(item_id, batch_id, size)
                if os.path.exists(path):
                    os.remove(path)


class ZipManager:
    def __init__(self):
        self.zips = {}

    def add_file(self, name, filepath, mtime):
        match = re.fullmatch(r'(\d{10})(?:-([SML]))?\.([a-zA-Z0-9]+)', name)
        if not match:
            raise ValueError(f'invalid cover filename: {name}')
        cover_id, suffix, _ = match.groups()
        size = suffix.lower() if suffix else ''
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zips:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            z = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zips[path] = (z, set(z.namelist()))
        z, names = self.zips[path]
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source:
                z.writestr(info, source.read())
            names.add(name)
        return f'{Batch.get_relpath(item_id, batch_id, size)}/{name}'

    def close(self):
        for z, _ in self.zips.values():
            z.close()
        self.zips.clear()


def get_zipfile(name):
    match = re.fullmatch(r'(\d{10})(?:-([SML]))?\.[a-zA-Z0-9]+', name)
    if not match:
        raise ValueError(f'invalid cover filename: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
    path = Batch.get_abspath(item_id, batch_id, (match.group(2) or '').lower())
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def open_zipfile(name):
    return get_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as z:
        return sum(n.lower().endswith('.jpg') for n in z.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                   capture_output=True, text=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], capture_output=True, text=True, check=True)
        found = zip_filename in (line.strip().split('/')[-1] for line in result.stdout.splitlines())
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10_000 + 1) * 10_000 - 1

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        item_id, batch_id = Batch(item_id, batch_id)._norm_ids()
        start_id = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end_id = CoverDB._get_batch_end_id(start_id)
        database = db.getdb()
        transaction = database.transaction()
        try:
            for row in database.select('cover', where='id >= $start_id AND id <= $end_id '
                                       'AND archived = true AND failed = false',
                                       vars=locals()):
                fields = {f'filename_{size}' if size else 'filename':
                          Cover.get_cover_url(row.id, size, ext) for size in SIZES}
                database.update('cover', where='id=$id AND archived=true AND failed=false',
                                vars={'id': row.id}, uploaded=True, **fields)
        except Exception:
            transaction.rollback()
            raise
        else:
            transaction.commit()


def archive(test=True):
    """Stage one batch of unarchived covers in uncompressed zip files."""
    database = db.getdb()
    rows = database.select('cover', where='archived=false AND failed=false', order='id', limit=10_000)
    grouped = {}
    for row in rows:
        key = Cover.id_to_item_and_batch_id(row.id)
        grouped.setdefault(key, []).append(row)
    for (item_id, batch_id), covers in grouped.items():
        batch = Batch(item_id, batch_id)
        with batch.lock():
            manager = ZipManager()
            try:
                for row in covers:
                    cover = Cover(row)
                    if not cover.valid_files():
                        if not test:
                            database.update('cover', where='id=$id', vars={'id': row.id}, failed=True)
                        continue
                    if isinstance(row.created, str):
                        from infogami.infobase import utils
                        row.created = utils.parse_datetime(row.created)
                    timestamp = time.mktime(row.created.timetuple())
                    fields = {}
                    for size, field, path in cover.files():
                        suffix = f'-{size.upper()}' if size else ''
                        name = f'{row.id:010d}{suffix}.{os.path.splitext(path)[1].lstrip(".")}'
                        fields[field] = manager.add_file(name, path, timestamp)
                    if not test:
                        database.update('cover', where='id=$id AND archived=false',
                                        vars={'id': row.id}, archived=True, uploaded=False, **fields)
                manager.close()
            finally:
                manager.close()
